template:
PREFIX aegis: <http://aegis.gastown.local/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?iri ?naturalKey ?kind ?label ?body ?sourceKind ?recordedAt ?reviewAfter ?expiresAt ?status ?cursor WHERE {
  ?iri aegis:naturalKey ?naturalKey ;
       a ?kind ;
       rdfs:label ?label ;
       aegis:recordedAt ?recordedAt .
  OPTIONAL { ?iri rdfs:comment ?body }
  OPTIONAL { ?iri aegis:sourceKind ?sourceKind }
  OPTIONAL { ?iri aegis:reviewAfter ?reviewAfter }
  OPTIONAL { ?iri aegis:expiresAt ?expiresAt }
  {
    ?iri aegis:recordedAt ?currentAt .
    FILTER NOT EXISTS { ?iri aegis:supersededBy ?anyNewer }
    BIND("current" AS ?status)
    BIND(STR(?currentAt) AS ?cursor)
  } UNION {
    ?iri aegis:supersededBy ?newer .
    ?newer aegis:recordedAt ?supersededAt .
    BIND("superseded" AS ?status)
    BIND(STR(?supersededAt) AS ?cursor)
  }
  BIND(STR(?iri) AS ?iriKey)
  FILTER(?cursor > '{since}' || (?cursor = '{since}' && ?iriKey > '{since_iri}'))
}
ORDER BY ?cursor ?iriKey
LIMIT 51
